    {
      "id": "BROWSER-1",
      "title": "removeChild fails when blur and Enter both fire on empty edit input",
      "spec": "features/browser-acceptance-defects.feature:27",
      "acceptance_failure": "should remove the item if an empty text string was entered",
      "root_cause": "finishEditing is called twice (blur + keydown), causing re-entrant removeChild in the orphan-removal loop",
      "fix指引": [
        "Guard the orphan-removal loop: check parentNode before calling removeChild",
        "Clear editingId in destroyTodo to prevent stale editing state"
      ]
    },
    {
      "id": "BROWSER-2",
      "title": "Filter click handler prevents hash update, breaking back button",
      "spec": "features/browser-acceptance-defects.feature:66",
      "acceptance_failure": "should respect the back button",
      "root_cause": "Filter link click handler calls e.preventDefault() without updating window.location.hash, so history.back() has nothing to restore",
      "fix指引": [
        "Remove e.preventDefault() from the filter click handler and let the default anchor behavior update the hash",
        "OR update window.location.hash manually in the click handler before calling setFilter"
      ]
    }
  ]
}
